      }
    }
  },
  "universe": {
    "n_genes_input_matrix": 12000,
    "n_genes_after_expression_filter": 9782,
    "n_genes_tested_for_DE_nonNA_padj": 9402,
    "n_genes_ranked_for_gsea": 9782,
    "note": "GSEA universe = all 9,782 genes surviving the DESeq2 expression filter and receiving a Wald statistic, not just the 875 padj<0.05 DE genes -- this is the standard preranked-GSEA universe, not a hypergeometric overlap test against a p-value-thresholded gene list."
  },
  "shallow_sample_handling": {
    "sample": "sample_01",
    "condition": "control",
    "library_size": 420347,
    "cohort_median_library_size": 1614280,
    "ratio_to_median": 0.26,
    "detected_genes": 10918,
    "size_factor_deseq2": 0.2835,
    "qc_flag_status": "Below the literal 1/4-of-median low-depth threshold cutoff of 0.25 by only 0.01 (ratio 0.260); did NOT trip the automated low-depth flag (n_low_depth_samples=0 in T1S1) but is unambiguously the cohort's depth outlier (next-lowest sample is at 0.71x median).",
    "pca_behavior": "Falls cleanly within the control cluster on PC1 (condition axis, 55.1% variance); is a PC2 outlier (PC2=+20.56 vs -5.82 to +2.68 for all other samples) consistent with depth-driven technical noise, not a condition-related effect.",
    "cooks_distance_check_at_DE_step": "0 Cook's-distance-flagged (NA pvalue) genes attributed to sample_01, identical to every other sample -- no evidence sample_01 drives outlier-level leverage on any tested gene.",
    "decision": "KEPT in the final DESeq2 model (design ~condition, all 12 samples).",
    "rationale": "Per the plan's keep_inspect_report policy, library depth alone is not a removal criterion. sample_01 clusters correctly by condition (PC1, hierarchical clustering) and DESeq2's internal size-factor normalization together with the Cook's-distance diagnostic (0 outlier genes attributed to it, same as every other sample) show no evidence it distorts the DE fit. Its low depth widens its contribution to per-gene dispersion/CI width via its size factor (0.2835, lowest in the cohort) rather than biasing fold changes systematically."
  },
  "gc_length_bias_diagnostic": {
    "tool": "Pearson/Spearman correlation, log2(gene length) vs log2(normalized-count-to-geometric-mean ratio), per sample",
    "outcome": "No length-driven trend detected in any of the 12 samples (max |Pearson r| = 0.0176, sample sample_07, p > 0.08 for all samples).",
    "caveat": "GC content itself could not be assessed -- only gene length was available in the input reference table. Absence of a length trend does not rule out a GC-content-driven trend. This is a diagnostic on this count matrix, not a validation of the (unstated) upstream quantification pipeline. No length/GC correction (e.g. cqn, EDASeq) was applied to the counts; DESeq2 was run on raw, uncorrected counts as intended."
  },
